// The config parameter MUST come from @JacksonInject and never from user input
if (config == null) {
  throw new IllegalArgumentException(
      "JavaScript is disabled or not properly configured. JavaScriptConfig must be injected by the system."
  );
}

this.dimension = dimension;
this.function = function;
this.extractionFn = extractionFn;

